import Foundation

// MARK: - App Language (5 languages)

enum AppLanguage: String, CaseIterable, Codable, Sendable {
    case es = "es"
    case en = "en"
    case de = "de"
    case fr = "fr"
    case pt = "pt"

    var displayName: String {
        switch self {
        case .es: return "Español"
        case .en: return "English"
        case .de: return "Deutsch"
        case .fr: return "Français"
        case .pt: return "Português"
        }
    }

    var flag: String {
        switch self {
        case .es: return "🇪🇸"
        case .en: return "🇺🇸"
        case .de: return "🇩🇪"
        case .fr: return "🇫🇷"
        case .pt: return "🇧🇷"
        }
    }

    /// Auto-detect from device locale
    static func fromDeviceLocale() -> AppLanguage {
        let langCode = Locale.current.language.languageCode?.identifier ?? "es"
        switch langCode {
        case "en": return .en
        case "de": return .de
        case "fr": return .fr
        case "pt": return .pt
        default: return .es
        }
    }
}

