        "score_budget_adherence": [.es: "Adherencia a presupuestos", .en: "Budget adherence", .de: "Budgeteinhaltung", .fr: "Respect du budget", .pt: "Aderência ao orçamento"],
        "score_budget_adherence_desc": [.es: "Mide que tan bien te mantienes dentro de tus presupuestos mensuales. Un puntaje alto significa que no excedes tus limites.", .en: "Measures how well you stay within your monthly budgets. A high score means you don't exceed your limits.", .de: "Misst, wie gut du deine monatlichen Budgets einhältst. Ein hoher Score bedeutet, dass du deine Grenzen nicht überschreitest.", .fr: "Mesure dans quelle mesure tu respectes tes budgets mensuels. Un score élevé signifie que tu ne dépasses pas tes limites.", .pt: "Mede o quão bem você se mantém dentro dos seus orçamentos mensais. Uma pontuação alta significa que não excede seus limites."],
        "score_budget_tip_low": [.es: "Intenta establecer presupuestos mas realistas basados en tus gastos de los ultimos 3 meses.", .en: "Try setting more realistic budgets based on your spending over the last 3 months.", .de: "Versuche, realistischere Budgets basierend auf deinen Ausgaben der letzten 3 Monate zu setzen.", .fr: "Essaie de fixer des budgets plus réalistes basés sur tes dépenses des 3 derniers mois.", .pt: "Tente definir orçamentos mais realistas com base nos seus gastos dos últimos 3 meses."],
        "score_budget_tip_high": [.es: "Excelente control de presupuestos. Sigue asi.", .en: "Excellent budget control. Keep it up.", .de: "Ausgezeichnete Budgetkontrolle. Weiter so.", .fr: "Excellent contrôle du budget. Continue ainsi.", .pt: "Excelente controle de orçamento. Continue assim."],
        "score_savings_rate_title": [.es: "Tasa de ahorro", .en: "Savings rate", .de: "Sparquote", .fr: "Taux d'épargne", .pt: "Taxa de poupança"],
        "score_savings_rate_desc": [.es: "Porcentaje de tus ingresos que logras ahorrar cada mes. Lo ideal es ahorrar al menos el 20% de tus ingresos.", .en: "Percentage of your income you save each month. Ideally, save at least 20% of your income.", .de: "Prozentsatz deines Einkommens, den du jeden Monat sparst. Idealerweise sparst du mindestens 20%.", .fr: "Pourcentage de tes revenus que tu épargnes chaque mois. L'idéal est d'épargner au moins 20%.", .pt: "Porcentagem da sua renda que você poupa a cada mês. O ideal é poupar pelo menos 20%."],
        "score_savings_tip_low": [.es: "Establece una transferencia automatica el dia de pago para forzar el ahorro antes de gastar.", .en: "Set up an automatic transfer on payday to force savings before spending.", .de: "Richte am Zahltag eine automatische Überweisung ein, um vor dem Ausgeben zu sparen.", .fr: "Configure un virement automatique le jour de paie pour forcer l'épargne avant de dépenser.", .pt: "Configure uma transferência automática no dia do pagamento para forçar a poupança antes de gastar."],
        "score_savings_tip_high": [.es: "Tu tasa de ahorro es saludable. Considera diversificar en diferentes metas.", .en: "Your savings rate is healthy. Consider diversifying into different goals.", .de: "Deine Sparquote ist gesund. Erwäge, in verschiedene Ziele zu diversifizieren.", .fr: "Ton taux d'épargne est sain. Envisage de diversifier dans différents objectifs.", .pt: "Sua taxa de poupança é saudável. Considere diversificar em metas diferentes."],
        "score_debt_title": [.es: "Manejo de deudas", .en: "Debt management", .de: "Schuldenmanagement", .fr: "Gestion des dettes", .pt: "Gestão de dívidas"],
        "score_debt_desc": [.es: "Evalua como manejas las deudas con tu pareja. Menos deudas pendientes y pagos puntuales mejoran este score.", .en: "Evaluates how you manage debts with your partner. Fewer pending debts and timely payments improve this score.", .de: "Bewertet, wie du Schulden mit deinem Partner verwaltest. Weniger ausstehende Schulden und pünktliche Zahlungen verbessern diesen Score.", .fr: "Évalue la gestion de tes dettes avec ton partenaire. Moins de dettes en attente et des paiements ponctuels améliorent ce score.", .pt: "Avalia como você gerencia dívidas com seu parceiro. Menos dívidas pendentes e pagamentos pontuais melhoram este score."],
        "score_debt_tip_low": [.es: "Intenta saldar las deudas pendientes lo antes posible. Usa la funcion de liquidar deudas.", .en: "Try to settle pending debts as soon as possible. Use the settle debts feature.", .de: "Versuche, ausstehende Schulden so schnell wie möglich zu begleichen.", .fr: "Essaie de régler les dettes en attente le plus tôt possible.", .pt: "Tente quitar as dívidas pendentes o mais rápido possível."],
        "score_debt_tip_high": [.es: "Buen manejo de deudas. Mantener cuentas claras fortalece la relacion.", .en: "Good debt management. Keeping clear accounts strengthens the relationship.", .de: "Gutes Schuldenmanagement. Klare Konten stärken die Beziehung.", .fr: "Bonne gestion des dettes. Des comptes clairs renforcent la relation.", .pt: "Boa gestão de dívidas. Manter contas claras fortalece o relacionamento."],
        "score_consistency_title": [.es: "Consistencia en registro", .en: "Logging consistency", .de: "Erfassungskonsistenz", .fr: "Régularité d'enregistrement", .pt: "Consistência no registro"],
        "score_consistency_desc": [.es: "Mide que tan regularmente registras tus transacciones. La constancia es clave para el control financiero.", .en: "Measures how regularly you log your transactions. Consistency is key for financial control.", .de: "Misst, wie regelmäßig du deine Transaktionen erfasst. Konsistenz ist der Schlüssel zur Finanzkontrolle.", .fr: "Mesure la régularité avec laquelle tu enregistres tes transactions. La constance est la clé du contrôle financier.", .pt: "Mede a regularidade com que você registra suas transações. A constância é fundamental para o controle financeiro."],
        "score_consistency_tip_low": [.es: "Registra tus gastos inmediatamente despues de hacerlos. Usa la entrada por voz para mayor rapidez.", .en: "Log your expenses right after making them. Use voice input for speed.", .de: "Erfasse deine Ausgaben sofort. Nutze die Spracheingabe für mehr Schnelligkeit.", .fr: "Enregistre tes dépenses immédiatement après les avoir faites. Utilise la saisie vocale.", .pt: "Registre seus gastos imediatamente após fazê-los. Use a entrada por voz para mais rapidez."],
        "score_consistency_tip_high": [.es: "Gran habito de registro. Tu racha de dias consecutivos se ve genial.", .en: "Great logging habit. Your streak of consecutive days looks amazing.", .de: "Tolle Erfassungsgewohnheit. Deine Serie aufeinanderfolgender Tage sieht großartig aus.", .fr: "Excellente habitude d'enregistrement. Ta série de jours consécutifs est superbe.", .pt: "Ótimo hábito de registro. Sua sequência de dias consecutivos está incrível."],
        "score_goal_title": [.es: "Progreso en metas", .en: "Goal progress", .de: "Zielfortschritt", .fr: "Progrès des objectifs", .pt: "Progresso nas metas"],
        "score_goal_desc": [.es: "Avance hacia tus metas de ahorro. Considera tanto el progreso actual como la velocidad de ahorro.", .en: "Progress toward your savings goals. Considers both current progress and savings velocity.", .de: "Fortschritt bei deinen Sparzielen. Berücksichtigt sowohl den aktuellen Fortschritt als auch die Spargeschwindigkeit.", .fr: "Avancement vers tes objectifs d'épargne. Prend en compte le progrès actuel et la vitesse d'épargne.", .pt: "Avanço nas suas metas de poupança. Considera tanto o progresso atual quanto a velocidade de poupança."],
        "score_goal_tip_low": [.es: "Contribuye aunque sea una pequena cantidad a tus metas cada semana. La constancia supera a los grandes montos.", .en: "Contribute even a small amount to your goals each week. Consistency beats large amounts.", .de: "Trage jede Woche auch nur einen kleinen Betrag zu deinen Zielen bei. Konsistenz schlägt große Beträge.", .fr: "Contribue même une petite somme à tes objectifs chaque semaine. La constance bat les gros montants.", .pt: "Contribua mesmo que seja um valor pequeno para suas metas toda semana. A constância supera grandes valores."],
        "score_goal_tip_high": [.es: "Vas muy bien con tus metas. Considera crear una nueva meta para mantener la motivacion.", .en: "You're doing great with your goals. Consider creating a new one to stay motivated.", .de: "Du machst deine Ziele großartig. Erstelle ein neues Ziel, um motiviert zu bleiben.", .fr: "Tu avances très bien avec tes objectifs. Envisage d'en créer un nouveau pour rester motivé.", .pt: "Você está indo muito bem com suas metas. Considere criar uma nova para manter a motivação."],
        "score_diversity_title": [.es: "Diversificacion de gastos", .en: "Spending diversification", .de: "Ausgabendiversifizierung", .fr: "Diversification des dépenses", .pt: "Diversificação de gastos"],
        "score_diversity_desc": [.es: "Evalua si tus gastos estan balanceados entre categorias o si hay una concentracion excesiva en una sola area.", .en: "Evaluates if your spending is balanced across categories or overly concentrated in one area.", .de: "Bewertet, ob deine Ausgaben zwischen Kategorien ausgewogen oder in einem Bereich zu konzentriert sind.", .fr: "Évalue si tes dépenses sont équilibrées entre catégories ou trop concentrées dans un seul domaine.", .pt: "Avalia se seus gastos estão equilibrados entre categorias ou excessivamente concentrados em uma área."],
        "score_diversity_tip_low": [.es: "Revisa si hay una categoria dominando tus gastos. Busca alternativas mas economicas.", .en: "Check if one category dominates your spending. Look for cheaper alternatives.", .de: "Prüfe, ob eine Kategorie deine Ausgaben dominiert. Suche günstigere Alternativen.", .fr: "Vérifie si une catégorie domine tes dépenses. Cherche des alternatives moins chères.", .pt: "Verifique se há uma categoria dominando seus gastos. Busque alternativas mais econômicas."],
        "score_diversity_tip_high": [.es: "Tus gastos estan bien distribuidos entre categorias.", .en: "Your spending is well distributed across categories.", .de: "Deine Ausgaben sind gut über die Kategorien verteilt.", .fr: "Tes dépenses sont bien réparties entre les catégories.", .pt: "Seus gastos estão bem distribuídos entre categorias."],
        "score_improve_title": [.es: "🚀 Como mejorar tu score", .en: "🚀 How to improve your score", .de: "🚀 So verbesserst du deinen Score", .fr: "🚀 Comment améliorer ton score", .pt: "🚀 Como melhorar seu score"],
        "score_improve_1": [.es: "Registra todos tus gastos diariamente para mejorar la consistencia.", .en: "Log all your expenses daily to improve consistency.", .de: "Erfasse alle deine Ausgaben täglich, um die Konsistenz zu verbessern.", .fr: "Enregistre toutes tes dépenses quotidiennement pour améliorer la régularité.", .pt: "Registre todos os seus gastos diariamente para melhorar a consistência."],
        "score_improve_2": [.es: "Establece presupuestos realistas y respétalos durante todo el mes.", .en: "Set realistic budgets and stick to them all month.", .de: "Setze realistische Budgets und halte sie den ganzen Monat ein.", .fr: "Fixe des budgets réalistes et respecte-les tout le mois.", .pt: "Defina orçamentos realistas e respeite-os durante todo o mês."],
        "score_improve_3": [.es: "Contribuye regularmente a tus metas de ahorro, aunque sean montos pequenos.", .en: "Contribute regularly to your savings goals, even small amounts.", .de: "Trage regelmäßig zu deinen Sparzielen bei, auch kleine Beträge.", .fr: "Contribue régulièrement à tes objectifs d'épargne, même de petits montants.", .pt: "Contribua regularmente para suas metas de poupança, mesmo que sejam valores pequenos."],
        "score_improve_4": [.es: "Liquida deudas pendientes con tu pareja lo antes posible.", .en: "Settle pending debts with your partner as soon as possible.", .de: "Begleiche ausstehende Schulden mit deinem Partner so schnell wie möglich.", .fr: "Règle les dettes en attente avec ton partenaire le plus tôt possible.", .pt: "Quite dívidas pendentes com seu parceiro o mais rápido possível."],
        "score_improve_5": [.es: "Diversifica tus gastos evitando concentrar demasiado en una sola categoria.", .en: "Diversify your spending by avoiding too much concentration in one category.", .de: "Diversifiziere deine Ausgaben, indem du zu starke Konzentration in einer Kategorie vermeidest.", .fr: "Diversifie tes dépenses en évitant de trop concentrer dans une seule catégorie.", .pt: "Diversifique seus gastos evitando concentrar demais em uma única categoria."],

