        // MARK: - Tutorial — Module 1: Registra tu primer gasto
        "tutorial_m1_title": [.es: "Registra tu primer gasto", .en: "Record your first expense", .de: "Erfasse deine erste Ausgabe", .fr: "Enregistre ta première dépense", .pt: "Registre seu primeiro gasto"],
        "tutorial_m1_desc": [.es: "Toca el botón + en la pestaña Gastos para registrar un gasto. Puedes escribir el monto o usar tu voz.", .en: "Tap the + button in the Expenses tab to record an expense. You can type the amount or use your voice.", .de: "Tippe auf den +-Knopf im Tab Ausgaben, um eine Ausgabe zu erfassen. Du kannst den Betrag eintippen oder deine Stimme nutzen.", .fr: "Touche le bouton + dans l'onglet Dépenses pour enregistrer une dépense. Tu peux taper le montant ou utiliser ta voix.", .pt: "Toque no botão + na aba Gastos para registrar um gasto. Você pode digitar o valor ou usar a voz."],
        "tutorial_m1_tip": [.es: "Pon el comercio para que la próxima vez te lo sugiera automáticamente.", .en: "Add the merchant so it gets suggested automatically next time.", .de: "Gib das Geschäft an, damit es beim nächsten Mal automatisch vorgeschlagen wird.", .fr: "Indique le commerce pour qu'il soit suggéré automatiquement la prochaine fois.", .pt: "Coloque o comércio para que seja sugerido automaticamente da próxima vez."],
        "tutorial_m1_cta": [.es: "Ir a Gastos", .en: "Go to Expenses", .de: "Zu Ausgaben", .fr: "Aller aux Dépenses", .pt: "Ir para Gastos"],

        // MARK: - Tutorial — Module 2: Configura tus gastos fijos
        "tutorial_m2_title": [.es: "Configura tus gastos fijos", .en: "Set up your fixed expenses", .de: "Richte deine Fixkosten ein", .fr: "Configure tes charges fixes", .pt: "Configure seus gastos fixos"],
        "tutorial_m2_desc": [.es: "Los gastos fijos son los que pagas cada mes: arriendo, servicios, suscripciones. Regístralos una vez y aparecerán cada mes como checklist.", .en: "Fixed expenses are the ones you pay every month: rent, utilities, subscriptions. Add them once and they'll appear each month as a checklist.", .de: "Fixkosten sind die, die du jeden Monat zahlst: Miete, Nebenkosten, Abos. Einmal erfassen und sie erscheinen jeden Monat als Checkliste.", .fr: "Les charges fixes sont celles que tu paies chaque mois: loyer, services, abonnements. Enregistre-les une fois et elles apparaîtront chaque mois en checklist.", .pt: "Gastos fixos são os que você paga todo mês: aluguel, contas, assinaturas. Registre uma vez e aparecerão a cada mês como checklist."],
        "tutorial_m2_tip": [.es: "Marca cada gasto como pagado cuando lo pagues para llevar el control.", .en: "Tick each expense as paid when you pay it to stay on top of things.", .de: "Hake jede Ausgabe als bezahlt ab, sobald du sie bezahlst, um den Überblick zu behalten.", .fr: "Coche chaque dépense comme payée quand tu la paies pour garder le contrôle.", .pt: "Marque cada gasto como pago quando o pagar para manter o controle."],
        "tutorial_m2_cta": [.es: "Ir a Fijos", .en: "Go to Fixed", .de: "Zu Fixkosten", .fr: "Aller aux Fixes", .pt: "Ir para Fixos"],

        // MARK: - Tutorial — Module 3: Conecta con tu pareja
        "tutorial_m3_title": [.es: "Conecta con tu pareja", .en: "Connect with your partner", .de: "Verbinde dich mit deinem Partner", .fr: "Connecte-toi avec ton/ta partenaire", .pt: "Conecte-se com seu parceiro(a)"],
        "tutorial_m3_desc": [.es: "Si compartes gastos con alguien, vincúlate. Uno genera un código, el otro lo ingresa. Así pueden dividir gastos y ver finanzas juntos.", .en: "If you share expenses with someone, link up. One generates a code, the other enters it. This way you can split expenses and see your finances together.", .de: "Wenn du Ausgaben mit jemandem teilst, verbinde dich. Einer erstellt einen Code, der andere gibt ihn ein. So könnt ihr Ausgaben aufteilen und Finanzen gemeinsam sehen.", .fr: "Si tu partages des dépenses avec quelqu'un, lie-toi. L'un génère un code, l'autre le saisit. Ainsi vous pouvez répartir les dépenses et voir vos finances ensemble.", .pt: "Se compartilha gastos com alguém, vincule-se. Um gera um código, o outro insere. Assim podem dividir gastos e ver as finanças juntos."],
        "tutorial_m3_tip": [.es: "Pueden elegir cómo dividir: 50/50, proporcional al ingreso, o como quieran.", .en: "You can choose how to split: 50/50, proportional to income, or any way you want.", .de: "Ihr könnt wählen, wie ihr aufteilt: 50/50, proportional zum Einkommen oder wie ihr wollt.", .fr: "Vous pouvez choisir comment répartir: 50/50, proportionnel aux revenus, ou comme vous voulez.", .pt: "Podem escolher como dividir: 50/50, proporcional à renda, ou como preferirem."],
        "tutorial_m3_cta": [.es: "Ir a Configuración", .en: "Go to Settings", .de: "Zu Einstellungen", .fr: "Aller aux Réglages", .pt: "Ir para Configurações"],

        // MARK: - Tutorial — Module 4: Divide gastos compartidos
        "tutorial_m4_title": [.es: "Divide gastos compartidos", .en: "Split shared expenses", .de: "Teile gemeinsame Ausgaben", .fr: "Partage les dépenses communes", .pt: "Divida gastos compartilhados"],
        "tutorial_m4_desc": [.es: "Cuando registras un gasto compartido, se divide automáticamente según lo que configuraste. Puedes ver tu parte en modo Individual y el total en modo Pareja.", .en: "When you record a shared expense, it's split automatically based on your setup. See your share in Individual mode and the total in Couple mode.", .de: "Wenn du eine geteilte Ausgabe erfasst, wird sie automatisch nach deiner Konfiguration aufgeteilt. Sieh deinen Anteil im Einzelmodus und das Gesamt im Paarmodus.", .fr: "Quand tu enregistres une dépense partagée, elle se divise automatiquement selon ta config. Vois ta part en mode Individuel et le total en mode Couple.", .pt: "Quando você registra um gasto compartilhado, ele é dividido automaticamente conforme sua configuração. Veja sua parte em modo Individual e o total em modo Casal."],
        "tutorial_m4_tip": [.es: "Toca el toggle 'Individual/Pareja' en cualquier pestaña para cambiar la vista.", .en: "Tap the 'Individual/Couple' toggle in any tab to switch the view.", .de: "Tippe auf den 'Einzeln/Paar'-Schalter in jedem Tab, um die Ansicht zu wechseln.", .fr: "Touche le bouton 'Individuel/Couple' dans n'importe quel onglet pour changer de vue.", .pt: "Toque no toggle 'Individual/Casal' em qualquer aba para mudar a visualização."],
        "tutorial_m4_cta": [.es: "Ir a Nosotros", .en: "Go to Us", .de: "Zu Wir", .fr: "Aller à Nous", .pt: "Ir para Nós"],

        // MARK: - Tutorial — Module 5: Crea una meta de ahorro
        "tutorial_m5_title": [.es: "Crea una meta de ahorro", .en: "Create a savings goal", .de: "Erstelle ein Sparziel", .fr: "Crée un objectif d'épargne", .pt: "Crie uma meta de poupança"],
        "tutorial_m5_desc": [.es: "Define un objetivo: vacaciones, fondo de emergencia, compra grande. Pon el monto y ve tu progreso.", .en: "Define a goal: vacation, emergency fund, big purchase. Set the amount and watch your progress.", .de: "Definiere ein Ziel: Urlaub, Notgroschen, größere Anschaffung. Lege den Betrag fest und beobachte deinen Fortschritt.", .fr: "Définis un objectif: vacances, fonds d'urgence, gros achat. Fixe le montant et regarde tes progrès.", .pt: "Defina um objetivo: férias, fundo de emergência, compra grande. Coloque o valor e veja seu progresso."],
        "tutorial_m5_tip": [.es: "Puedes crear metas individuales o en pareja.", .en: "You can create individual or couple goals.", .de: "Du kannst individuelle oder Paar-Ziele erstellen.", .fr: "Tu peux créer des objectifs individuels ou en couple.", .pt: "Pode criar metas individuais ou em casal."],
        "tutorial_m5_cta": [.es: "Ir a Metas", .en: "Go to Goals", .de: "Zu Zielen", .fr: "Aller aux Objectifs", .pt: "Ir para Metas"],

        // MARK: - Tutorial — Module 6: Acepta un reto financiero
        "tutorial_m6_title": [.es: "Acepta un reto financiero", .en: "Accept a financial challenge", .de: "Nimm eine finanzielle Herausforderung an", .fr: "Accepte un défi financier", .pt: "Aceite um desafio financeiro"],
        "tutorial_m6_desc": [.es: "Los retos son desafíos para mejorar tus finanzas: semana sin delivery, mes austero, registro perfecto. Completa retos para mejorar tu Score.", .en: "Challenges are dares to improve your finances: a week without delivery, an austere month, perfect tracking. Complete challenges to boost your Score.", .de: "Herausforderungen helfen dir, deine Finanzen zu verbessern: eine Woche ohne Lieferdienste, ein sparsamer Monat, perfekte Erfassung. Schließe sie ab, um deinen Score zu erhöhen.", .fr: "Les défis sont des challenges pour améliorer tes finances: une semaine sans livraison, un mois sobre, un suivi parfait. Complète des défis pour booster ton Score.", .pt: "Os desafios servem para melhorar suas finanças: semana sem delivery, mês econômico, registro perfeito. Complete desafios para melhorar seu Score."],
        "tutorial_m6_tip": [.es: "Empieza por uno fácil de 7 días para agarrar ritmo.", .en: "Start with an easy 7-day one to build momentum.", .de: "Fang mit einer einfachen 7-Tage-Herausforderung an, um Schwung zu holen.", .fr: "Commence par un facile de 7 jours pour prendre le rythme.", .pt: "Comece com um fácil de 7 dias para pegar ritmo."],
        "tutorial_m6_cta": [.es: "Ir a Retos", .en: "Go to Challenges", .de: "Zu Herausforderungen", .fr: "Aller aux Défis", .pt: "Ir para Desafios"],

        // MARK: - Tutorial — Module 7: Planifica un viaje
        "tutorial_m7_title": [.es: "Planifica un viaje", .en: "Plan a trip", .de: "Plane eine Reise", .fr: "Planifie un voyage", .pt: "Planeje uma viagem"],
        "tutorial_m7_desc": [.es: "Crea un viaje con presupuesto por categoría (vuelos, hotel, comida). Elige ahorrar con aporte mensual fijo y se creará un gasto fijo automático.", .en: "Create a trip with a per-category budget (flights, hotel, food). Choose to save with a fixed monthly contribution and a recurring expense will be created automatically.", .de: "Erstelle eine Reise mit Budget pro Kategorie (Flüge, Hotel, Essen). Wähle einen festen monatlichen Beitrag und es wird automatisch eine wiederkehrende Ausgabe erstellt.", .fr: "Crée un voyage avec un budget par catégorie (vols, hôtel, nourriture). Choisis d'épargner avec un apport mensuel fixe et une dépense récurrente sera créée automatiquement.", .pt: "Crie uma viagem com orçamento por categoria (voos, hotel, comida). Escolha poupar com aporte mensal fixo e um gasto recorrente será criado automaticamente."],
        "tutorial_m7_tip": [.es: "El presupuesto total se calcula sumando las categorías.", .en: "The total budget is the sum of all categories.", .de: "Das Gesamtbudget ist die Summe aller Kategorien.", .fr: "Le budget total est la somme de toutes les catégories.", .pt: "O orçamento total é a soma de todas as categorias."],
        "tutorial_m7_cta": [.es: "Ir a Viajes", .en: "Go to Trips", .de: "Zu Reisen", .fr: "Aller aux Voyages", .pt: "Ir para Viagens"],

        // MARK: - Tutorial — Module 8: Simula un crédito
        "tutorial_m8_title": [.es: "Simula un crédito", .en: "Simulate a loan", .de: "Simuliere einen Kredit", .fr: "Simule un crédit", .pt: "Simule um crédito"],
        "tutorial_m8_desc": [.es: "¿Quieres pedir un préstamo? El simulador te muestra cuánto pagarías de cuota, cuánto de intereses, y la tabla de amortización completa.", .en: "Thinking about a loan? The simulator shows you the monthly payment, the total interest, and the full amortization table.", .de: "Denkst du über einen Kredit nach? Der Simulator zeigt dir die monatliche Rate, die Gesamtzinsen und die komplette Tilgungstabelle.", .fr: "Tu envisages un prêt? Le simulateur t'affiche la mensualité, le total des intérêts et le tableau d'amortissement complet.", .pt: "Pensando em um empréstimo? O simulador mostra a parcela mensal, o total de juros e a tabela de amortização completa."],
        "tutorial_m8_tip": [.es: "Compara diferentes plazos para ver cuál te conviene más.", .en: "Compare different terms to see which one suits you best.", .de: "Vergleiche verschiedene Laufzeiten, um die beste für dich zu finden.", .fr: "Compare différentes durées pour voir laquelle te convient le mieux.", .pt: "Compare diferentes prazos para ver qual te convém mais."],
        "tutorial_m8_cta": [.es: "Ir al Simulador", .en: "Go to the Simulator", .de: "Zum Simulator", .fr: "Aller au Simulateur", .pt: "Ir ao Simulador"],

        // MARK: - Tutorial — Module 9: Revisa tu Score Fingether
        "tutorial_m9_title": [.es: "Revisa tu Score Fingether", .en: "Check your Fingether Score", .de: "Prüfe deinen Fingether-Score", .fr: "Consulte ton Score Fingether", .pt: "Veja seu Score Fingether"],
        "tutorial_m9_desc": [.es: "Tu Score va de 0 a 100 y mide tu salud financiera. Sube registrando gastos, manteniéndote bajo presupuesto, ahorrando, y completando retos.", .en: "Your Score goes from 0 to 100 and measures your financial health. It rises when you record expenses, stay within budget, save, and complete challenges.", .de: "Dein Score reicht von 0 bis 100 und misst deine finanzielle Gesundheit. Er steigt, wenn du Ausgaben erfasst, im Budget bleibst, sparst und Herausforderungen abschließt.", .fr: "Ton Score va de 0 à 100 et mesure ta santé financière. Il monte quand tu enregistres tes dépenses, restes dans ton budget, épargnes et complètes des défis.", .pt: "Seu Score vai de 0 a 100 e mede sua saúde financeira. Sobe registrando gastos, mantendo-se no orçamento, poupando e completando desafios."],
        "tutorial_m9_tip": [.es: "Toca cada categoría del desglose para ver cómo mejorar.", .en: "Tap each category of the breakdown to see how to improve.", .de: "Tippe auf jede Kategorie der Aufschlüsselung, um zu sehen, wie du dich verbessern kannst.", .fr: "Touche chaque catégorie de la répartition pour voir comment t'améliorer.", .pt: "Toque em cada categoria do detalhamento para ver como melhorar."],
        "tutorial_m9_cta": [.es: "Ver mi Score", .en: "View my Score", .de: "Meinen Score ansehen", .fr: "Voir mon Score", .pt: "Ver meu Score"],

        // MARK: - Tutorial — Module 10: Usa el calendario financiero
        "tutorial_m10_title": [.es: "Usa el calendario financiero", .en: "Use the financial calendar", .de: "Nutze den Finanzkalender", .fr: "Utilise le calendrier financier", .pt: "Use o calendário financeiro"],
        "tutorial_m10_desc": [.es: "El calendario te muestra con colores cuánto gastas cada día. Verde = poco, rojo = mucho. Te ayuda a ver patrones que no notas en listas.", .en: "The calendar shows in color how much you spend each day. Green = little, red = a lot. It helps you spot patterns you'd miss in lists.", .de: "Der Kalender zeigt farblich, wie viel du täglich ausgibst. Grün = wenig, rot = viel. So erkennst du Muster, die in Listen verborgen bleiben.", .fr: "Le calendrier t'affiche en couleur combien tu dépenses chaque jour. Vert = peu, rouge = beaucoup. Il t'aide à voir des tendances invisibles dans une liste.", .pt: "O calendário mostra com cores quanto você gasta cada dia. Verde = pouco, vermelho = muito. Ajuda a ver padrões que você não nota em listas."],
        "tutorial_m10_tip": [.es: "Toca un día para ver el detalle de gastos.", .en: "Tap a day to see the expense breakdown.", .de: "Tippe auf einen Tag, um die Ausgaben im Detail zu sehen.", .fr: "Touche un jour pour voir le détail des dépenses.", .pt: "Toque em um dia para ver o detalhe dos gastos."],
        "tutorial_m10_cta": [.es: "Ver calendario", .en: "View calendar", .de: "Kalender öffnen", .fr: "Voir le calendrier", .pt: "Ver calendário"],

        // MARK: - Tutorial — Module 11: Registra gastos con tu voz
        "tutorial_m11_title": [.es: "Registra gastos con tu voz", .en: "Record expenses with your voice", .de: "Erfasse Ausgaben per Sprache", .fr: "Enregistre des dépenses à la voix", .pt: "Registre gastos com a voz"],
        "tutorial_m11_desc": [.es: "Di 'gasté 30 mil en el supermercado' y la app lo registra. Funciona en los 5 idiomas.", .en: "Say 'I spent 30 thousand at the supermarket' and the app records it. Works in all 5 languages.", .de: "Sag 'ich habe 30 tausend im Supermarkt ausgegeben' und die App erfasst es. Funktioniert in allen 5 Sprachen.", .fr: "Dis 'j'ai dépensé 30 mille au supermarché' et l'app l'enregistre. Fonctionne dans les 5 langues.", .pt: "Diga 'gastei 30 mil no supermercado' e o app registra. Funciona nos 5 idiomas."],
        "tutorial_m11_tip": [.es: "Habla claro, di el monto y el lugar. La app sugiere la categoría.", .en: "Speak clearly, say the amount and the place. The app suggests the category.", .de: "Sprich klar, nenne Betrag und Ort. Die App schlägt die Kategorie vor.", .fr: "Parle clairement, indique le montant et le lieu. L'app suggère la catégorie.", .pt: "Fale claro, diga o valor e o lugar. O app sugere a categoria."],
        "tutorial_m11_cta": [.es: "Probar voz", .en: "Try voice", .de: "Sprache testen", .fr: "Essayer la voix", .pt: "Testar voz"],
    ]
    // swiftlint:enable line_length
}
